);

    typedef enum logic [1:0] {
        ST_WAIT  = 2'b00,
        ST_B2    = 2'b01,
        ST_B3    = 2'b10,
        ST_DONE  = 2'b11
    } state_t;

    state_t state;

    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= ST_WAIT;
            done      <= 1'b0;
            out_bytes <= 24'h0;
        end else begin
            case (state)
                ST_WAIT: begin
                    done <= 1'b0;
                    if (in[3]) begin
                        out_bytes[23:16] <= in;
                        state <= ST_B2;
                    end
                end

                ST_B2: begin
                    done <= 1'b0;
                    out_bytes[15:8] <= in;
                    state <= ST_B3;
                end

                ST_B3: begin
                    done <= 1'b0;
                    out_bytes[7:0] <= in;
                    state <= ST_DONE;
                end

                ST_DONE: begin
                    done <= 1'b1;
                    if (in[3]) begin
                        out_bytes[23:16] <= in;
                        state <= ST_B2;
                    end else begin
                        state <= ST_WAIT;
                    end
                end
            endcase
        end
    end

endmodule

